def paginate(items,page,size):
    pages = 0
    for i in range(page-1, len(items)):
        pages += 1
        if i+size >= len(items):
            break
    return {
        "items": items[:pages*size] if pages * size else [],
        "total": len(items),
        "pages": pages,
    }

